CREATE TABLE public.operational_settings (id boolean PRIMARY KEY DEFAULT true, email_enabled boolean NOT NULL DEFAULT false, alert_email text NOT NULL DEFAULT '', slack_enabled boolean NOT NULL DEFAULT false, slack_channel text NOT NULL DEFAULT '', alert_failures boolean NOT NULL DEFAULT true, alert_regressions boolean NOT NULL DEFAULT true, alert_high boolean NOT NULL DEFAULT true, block_catalog boolean NOT NULL DEFAULT true, retention_days integer NOT NULL DEFAULT 0, CONSTRAINT singleton_id CHECK(id), CONSTRAINT retention_range CHECK(retention_days BETWEEN 0 AND 3650));
GRANT SELECT,INSERT,UPDATE ON public.operational_settings TO authenticated;
GRANT ALL ON public.operational_settings TO service_role;
ALTER TABLE public.operational_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_operational_settings ON public.operational_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.catalog_security_approvals (scan_id uuid PRIMARY KEY REFERENCES public.security_scan_runs(id), approved_by uuid NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.catalog_security_approvals TO authenticated;
GRANT ALL ON public.catalog_security_approvals TO service_role;
ALTER TABLE public.catalog_security_approvals ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_approvals ON public.catalog_security_approvals FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.security_scan_runs ADD COLUMN IF NOT EXISTS high_regression boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.catalog_security_status() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scan public.security_scan_runs; enabled boolean; approved boolean; BEGIN IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; SELECT coalesce(block_catalog,true) INTO enabled FROM public.operational_settings LIMIT 1; enabled:=coalesce(enabled,true); SELECT * INTO scan FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1; SELECT EXISTS(SELECT 1 FROM public.catalog_security_approvals WHERE scan_id=scan.id) INTO approved; RETURN jsonb_build_object('blocked',enabled AND (scan.high_regression OR (scan.regression AND scan.high_count+scan.critical_count>0)) AND NOT approved,'scan_id',scan.id,'approved',approved); END; $$;
REVOKE ALL ON FUNCTION public.catalog_security_status() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.catalog_security_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.approve_catalog_security(_scan_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF length(btrim(_reason))<10 THEN RAISE EXCEPTION 'Provide a detailed approval reason'; END IF; IF _scan_id IS DISTINCT FROM (SELECT id FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1) THEN RAISE EXCEPTION 'Scan changed, refresh first'; END IF; INSERT INTO public.catalog_security_approvals(scan_id,approved_by,reason) VALUES(_scan_id,auth.uid(),btrim(_reason)) ON CONFLICT(scan_id) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.approve_catalog_security(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.approve_catalog_security(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.enforce_catalog_security() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE scan public.security_scan_runs; enabled boolean; BEGIN SELECT coalesce(block_catalog,true) INTO enabled FROM public.operational_settings LIMIT 1; IF coalesce(enabled,true) THEN SELECT * INTO scan FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1; IF (scan.high_regression OR (scan.regression AND scan.high_count+scan.critical_count>0)) AND NOT EXISTS(SELECT 1 FROM public.catalog_security_approvals WHERE scan_id=scan.id) THEN RAISE EXCEPTION 'Catalog blocked: high security regression. Request approval in Admin Security.' USING ERRCODE='42501'; END IF; END IF; RETURN NULL; END; $$;
CREATE TRIGGER catalog_security_gate BEFORE INSERT OR UPDATE OR DELETE ON public.products FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_catalog_security();
CREATE TRIGGER catalog_security_gate BEFORE INSERT OR UPDATE OR DELETE ON public.product_tags FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_catalog_security();
CREATE TRIGGER catalog_security_gate BEFORE INSERT OR UPDATE OR DELETE ON public.product_occasions FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_catalog_security();
CREATE TRIGGER catalog_security_gate BEFORE INSERT OR UPDATE OR DELETE ON public.product_segments FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_catalog_security();
CREATE OR REPLACE FUNCTION public.cleanup_web_vitals_history() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days integer; removed integer; BEGIN SELECT retention_days INTO days FROM public.operational_settings LIMIT 1; IF coalesce(days,0)=0 THEN RETURN 0; END IF; DELETE FROM public.web_vitals_reports WHERE created_at < now()-make_interval(days=>days); GET DIAGNOSTICS removed=ROW_COUNT; RETURN removed; END; $$;
REVOKE ALL ON FUNCTION public.cleanup_web_vitals_history() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cleanup_web_vitals_history() TO service_role;
CREATE OR REPLACE FUNCTION public.retry_image_processing_job(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; UPDATE public.image_processing_jobs SET status='pending',attempts=0,error=NULL,processed_at=NULL WHERE id=_id AND status IN ('error','retry'); IF NOT FOUND THEN RAISE EXCEPTION 'Job is not eligible for retry'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.retry_image_processing_job(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.retry_image_processing_job(uuid) TO authenticated;